#import "SPKLocalization.h"

NSString *SPKJailbreakPath(NSString *path)
{
    if (path.length == 0) {
        return path;
    }
    if ([path hasPrefix:@"/var/jb/"]) {
        return path;
    }
    if ([path hasPrefix:@"/"]) {
        return [@"/var/jb" stringByAppendingString:path];
    }
    return path;
}

NSDictionary<NSString *, NSString *> *SPKEmbeddedSimplifiedChineseTranslations(void)
{
    static NSDictionary<NSString *, NSString *> *table;
    static dispatch_once_t onceToken;
    dispatch_once(&onceToken, ^{
        NSString *payload = (
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
    @""
        );
        NSData *data = [[NSData alloc] initWithBase64EncodedString:payload options:0];
        if (data.length == 0) {
            return;
        }
        NSError *error = nil;
        id plist = [NSPropertyListSerialization propertyListWithData:data
                                                             options:0
                                                              format:NULL
                                                               error:&error];
        if ([plist isKindOfClass:[NSDictionary class]]) {
            table = [plist copy];
        }
    });
    return table;
}

NSString *SPKLocalizedString(NSString *text)
{
    if (text.length == 0) {
        return text;
    }
    NSDictionary<NSString *, NSString *> *table = SPKEmbeddedSimplifiedChineseTranslations();
    if (table.count == 0) {
        return text;
    }
    @try {
        NSString *translated = table[text];
        if (translated.length > 0) {
            return translated;
        }
        // Several literals reach here with trailing newlines / indentation.
        NSString *trimmed = [text stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];
        if (trimmed.length > 0 && trimmed.length != text.length) {
            NSString *trimmedTranslation = table[trimmed];
            if (trimmedTranslation.length > 0) {
                return trimmedTranslation;
            }
        }
    } @catch (NSException *exception) {
        return text;
    }
    return text;
}
